        "content": "name: Purge deleted image history\n\non:\n  schedule:\n    - cron: \"0 0 * * *\"\n  workflow_dispatch:\n\npermissions:\n  contents: write\n\nconcurrency:\n  group: purge-deleted-image-history\n  cancel-in-progress: false\n\njobs:\n  purge:\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    steps:\n      - name: Check out complete default-branch history\n        uses: actions/checkout@v4\n        with:\n          ref: ${{ github.event.repository.default_branch }}\n          fetch-depth: 0\n\n      - name: Install git-filter-repo\n        run: python3 -m pip install --disable-pip-version-check git-filter-repo\n\n      - name: Purge deleted image paths\n        id: filter\n        run: |\n          before_sha=\"$(git rev-parse HEAD)\"\n          remote_url=\"$(git remote get-url origin)\"\n\n          bash scripts/purge-deleted-image-history.sh\n\n          after_sha=\"$(git rev-parse HEAD)\"\n          {\n            echo \"before_sha=$before_sha\"\n            echo \"remote_url=$remote_url\"\n            if [[ \"$before_sha\" == \"$after_sha\" ]]; then\n              echo \"changed=false\"\n            else\n              echo \"changed=true\"\n            fi\n          } >> \"$GITHUB_OUTPUT\"\n\n      - name: Force-push rewritten history\n        if: steps.filter.outputs.changed == 'true'\n        env:\n          BEFORE_SHA: ${{ steps.filter.outputs.before_sha }}\n          REMOTE_URL: ${{ steps.filter.outputs.remote_url }}\n          TARGET_BRANCH: ${{ github.event.repository.default_branch }}\n        run: |\n          if git remote get-url origin >/dev/null 2>&1; then\n            git remote set-url origin \"$REMOTE_URL\"\n          else\n            git remote add origin \"$REMOTE_URL\"\n          fi\n\n          git push \\\n            --force-with-lease=\"refs/heads/${TARGET_BRANCH}:${BEFORE_SHA}\" \\\n            origin \"HEAD:refs/heads/${TARGET_BRANCH}\"\n"
